    out = []
    for m in re.finditer(r'\b' + typename + r'\s*\{', text):
        # skip the struct definition itself: `pub struct TypeName {`
        line_start = text.rfind('\n', 0, m.start()) + 1
        if 'struct' in text[line_start:m.start()]:
            continue
        i = m.end() - 1  # at '{'
        depth = 0
        j = i
        while j < len(text):
            ch = text[j]
            if ch == '"':
                j += 1
                while j < len(text) and text[j] != '"':
                    j += 2 if text[j] == '\\' else 1
            elif ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
                if depth == 0:
                    break
            j += 1
        body = text[i:j]
        if 'repeat_while_held' in body:
            continue
        out.append((i, j))
    return out

