///   * `end` = 排出去的**最后一个动作**发生的墙钟时刻。宏的收尾"兜底抬起"
///     就排在这里,所以它就是"这一轮跑完"的时点。
#[derive(Clone, Copy)]
struct MacroSpan {
    total: u64,
    end: Instant,
}

impl MacroSpan {
    /// 下一轮最早可以在哪一刻开始:`end + Duration::from_millis(gap)`,**严格晚于**
    /// `end`(即使 gap = 0 也 +1ms)。多出来的这一毫秒是必要的:同刻动作按入队顺序
    /// 执行,而下一轮是**后**追加进去的,真让它在同一刻跑就会排到收尾的"兜底抬起"
    /// **后面** —— 于是那一抬会把下一轮的按下一并抬掉。
    fn after_end(&self, gap_ms: u64) -> Instant {
        self.end + Duration::from_millis(gap_ms) + Duration::from_millis(1)
    }
}

/// 把一条宏展开为定时动作(W2-8 重建 —— "录制什么、释放什么")。
///
/// 录制步骤 = 照录制时间轴逐条重放:按下分配触点号落指、抬起抬指,时间差
/// 全部照录制;设置步骤 = 自包含的"按下-持续-抬起"。宏**不再**把事件重新塞回
/// 输入流(旧实现要经组合门控、物理镜像与 `sync_structures`,是"录制的点击+
/// 滑动回放不出来"的根因),一律直接排出具体动作。
///
/// 宏触点照旧要占设备端十指预算:落指前由执行端查 [`DEVICE_MAX_POINTERS`],
/// 挤不下就跳过该步并给出提示(见 `SchedAct::MacroClick` 的执行分支)。
fn schedule_macro(
    mac: &MacroAction,
    live_profile: &Profile,
    m: &Mapper,
    start: Instant,
    scheduled: &mut Vec<(Instant, SchedAct)>,
    plan: &mut MacroPlan,
) -> MacroSpan {
    let mut emit = MacroEmit {
        scheduled,
        pending: Vec::new(),
        seq: 0,
    };
    let mut span = schedule_macro_into(mac, live_profile, None, m, start, &mut emit, plan);
