/// 回归:长按重复模式下,宏**内部步骤的 `delay_ms` 依然生效** ——
/// 循环只是把"同一轮"再排一次,不改变一轮内部的时间轴。
#[test]
fn macro_repeat_keeps_inner_step_delays() {
    const KEY: u16 = 41;
    let mut f = TailFixture::new(KEY, 0, repeat_macro(true), false);
    let before = Instant::now();
    f.fire(true, true);
    let clicks: Vec<(Instant, bool)> = f
        .scheduled
        .iter()
        .filter_map(|(t, a)| match a {
            SchedAct::MacroClick { down, .. } => Some((*t, *down)),
            _ => None,
        })
        .collect();
    assert_eq!(
        clicks,
        vec![
            (before, true),
            (before + Duration::from_millis(100), false),
            (before + Duration::from_millis(300), false),
        ],
        "一轮内部照录制时间轴:100ms 抬起、第二根键等 200ms 后兜底抬起"
    );
}

/// 一条"有长按重复意义的"宏:第 1 根键按下 100ms 后抬起,再等 200ms
/// 由收尾兜底抬起第 2 根按着的键 —— 一轮 = 300ms,最后一个动作在 t=300。
fn repeat_macro(repeat: bool) -> Action {
    use crate::keymap::MacroStep;
    Action::Macro(MacroAction {
        steps: vec![
            MacroStep {
                code: 30,
                pressed: true,
                delay_ms: 0,
            },
            MacroStep {
                code: 30,
                pressed: false,
                delay_ms: 100,
            },
        ],
        instructions: Vec::new(),
        virtual_profile: None,
        repeat_while_held: repeat,
    })
}

/// 排程里属于"这一轮宏"的动作数(触点 + 系统键 + 轮盘 + FPS)。
/// 用来断言"一次只排一轮、不预排 N 轮"。
fn macro_round_count(scheduled: &[(Instant, SchedAct)]) -> usize {
    scheduled
        .iter()
        .filter(|(_, a)| {
            matches!(
                a,
                SchedAct::MacroClick { .. }
                    | SchedAct::MacroMove { .. }
                    | SchedAct::MacroAndroidKey { .. }
                    | SchedAct::MacroWheel { .. }
                    | SchedAct::MacroFps { .. }
            )
        })
        .count()
}

