        const ROUND_MS: u64 = 305;

        // ---- ① 按住:先跑一轮,跑完那一刻再排下一轮 ----
        let mut f = TailFixture::new(KEY, 0, repeat_macro(true), false);
        assert!(f.fire(true, true).is_none(), "触发按下不该被拒绝");
