        assert_eq!(clicks.len(), 4, "一轮 = 两对自包含的点按");
        let t0 = clicks[0].0;
        assert_eq!(
            clicks,
            vec![
                (t0, true),
                (t0 + Duration::from_millis(100), false),
                (t0 + Duration::from_millis(300), true),
                (t0 + Duration::from_millis(305), false),
            ],
            "第 1 轮照录制时间轴(100ms 抬起、再等 200ms 按下 B、5ms 后抬起)"
        );
        assert_eq!(
